#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    // Right to left: each value splits into the fewest parts <= limit, as evenly as possible.
    long long limit = a[n - 1], answer = 0;
    for (int i = n - 2; i >= 0; i--) {
        long long value = a[i], parts = max(1LL, (value + limit - 1) / limit);
        answer += parts - 1;
        limit = value / parts; // smallest (leftmost) part becomes the new bound
    }
    printf("%lld\n", answer);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) { st.nextToken(); a[i] = (long) st.nval; }
        // Right to left: each value splits into the fewest parts <= limit, as evenly as possible.
        long limit = a[n - 1], answer = 0;
        for (int i = n - 2; i >= 0; i--) {
            long value = a[i], parts = Math.max(1, (value + limit - 1) / limit);
            answer += parts - 1;
            limit = value / parts; // smallest (leftmost) part becomes the new bound
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Right to left: each value splits into the fewest parts <= limit, as evenly as possible.
	limit, answer := a[n-1], 0
	for i := n - 2; i >= 0; i-- {
		value := a[i]
		parts := max(1, (value+limit-1)/limit)
		answer += parts - 1
		limit = value / parts // smallest (leftmost) part becomes the new bound
	}
	fmt.Println(answer)
}
